from pathlib import Path
import json
cases=[]
urls={'00420':'https://healthservice.hse.ie/documents/6732/420_DOXOrubicin_CISplatin.pdf','00463':'https://healthservice.hse.ie/documents/6736/463_MAP.pdf','00596':'https://healthservice.hse.ie/documents/6743/596_Ifosfamide_Etoposide_IE.pdf'}
# Authoritative URL is taken from the accepted candidate/source metadata rather than assumed filenames.
pin=json.load(open(Path(__file__).with_name('input-manifest.json')))
for r in pin['protocols']:
 if r['code'] in urls:
  j=json.load(open(Path(__file__).parent/r['snapshot_path']));urls[r['code']]=j['metadata']['source_url']
def add(code,title,inputs,kind,rationale,lines,**checks):
 cases.append({'case_id':f'{code}-{1+sum(x["code"]==code for x in cases):02}','code':code,'title':title,'inputs':inputs,'expected':{'kind':kind,**checks},'source':{'url':urls[code],'retained_lines':lines,'rationale':rationale}})

for phase in ['baseline','on_treatment','restart']:
 base=dict(assessment_phase=phase,anc=2,platelets=180,crcl_ml_min=90,bilirubin_umol_l=10)
 add('00420',f'FN-related reduction survives false event flag when escalation proposed, {phase}',dict(**base,prior_fn=False,doxo_fn_reduced_previously=True,proposed_doxo_reescalation=True,prior_fn_recovered=True,current_neuropathy_grade=0),'review','The documented FN-related reduction is persistent for future doxorubicin courses; a contradictory event flag cannot authorise re-escalation.','L96–L100',component_attention=['doxorubicin'],match='escalat|future|persistent')
 add('00420',f'Clinical FN recovery is not established by normal current counts, {phase}',dict(**base,prior_fn=True,prior_anc_nadir=.4,prior_fn_recovered=False,restart_requested=True,restart_recovery_and_plan_confirmed=True),'hold','The prior FN reduction applies on recovery; a current count sample and generic restart confirmation cannot substitute for explicitly absent clinical recovery.','L96–L100',component_hold=['doxorubicin'])
 add('00420',f'Concurrent severe mouth toxicity and grade2neuropathy, {phase}',dict(**base,current_mucositis_grade=3,prior_mucositis_grade=0,current_neuropathy_grade=2,mucositis_recovery_confirmed=False),'hold','The two adverse events affect different drugs: doxorubicin reduction/recovery review versus cisplatin omission. Do not copy one percentage onto both.','L143–L149',component_attention=['doxorubicin'],component_hold=['cisplatin'])
 add('00420',f'Cardiac symptoms despite current LVEF65, {phase}',dict(**base,lvef_percent=65,symptomatic_cardiac_dysfunction=True,anthracycline_history_reconciled=True,planned_cumulative_doxorubicin_mg_m2=300),'review','Cardiac dysfunction requires specific assessment even with a reassuring EF and cumulative-dose reconciliation.','L72–L80; L181–L182',component_attention=['doxorubicin'],match='cardiac|heart')
 add('00420',f'ChildPughC despite normal absolute bilirubin, {phase}',dict(**base,child_pugh_c=True,current_neuropathy_grade=0),'hold','ChildPughC is an independent doxorubicin not-recommended category; normal bilirubin does not remove it or imply a cisplatin hepatic reduction.','L129–L140',component_hold=['doxorubicin'],component_not_stop=['cisplatin'])
for phase in ['baseline','restart']:
 add('00420',f'Cycle7outside six-course reference despite lifetime totalat450, {phase}',dict(assessment_phase=phase,cycle_number=7,prior_doxorubicin_mg_m2=375,planned_cumulative_doxorubicin_mg_m2=450,lvef_percent=65,anthracycline_history_reconciled=True),'review','The source course length and lifetime exposure are separate; remaining cumulative allowance does not establish a routine seventh cycle.','L29–L30; L43–L45',match='six|6|cycle|course')
for crcl in [None,100]:
 inp=dict(assessment_phase='restart',haemodialysis=True,bilirubin_umol_l=10,lvef_percent=65,anc=2,platelets=180,restart_requested=True,restart_recovery_and_plan_confirmed=True)
 if crcl is not None:inp['crcl_ml_min']=crcl
 add('00420',f'Dialysis cannot be cleared by numericCrCl{crcl}',inp,'hold','Source dialysis advice is drug-specific: cisplatin is not recommended while doxorubicin75%-of-original may be considered.','L127–L140',component_hold=['cisplatin'],component_attention=['doxorubicin'])
add('00420','Other anthracycline exposure unresolved despite low documented doxorubicin total',dict(assessment_phase='on_treatment',prior_doxorubicin_mg_m2=0,planned_cumulative_doxorubicin_mg_m2=400,other_anthracycline_exposure=True,anthracycline_history_reconciled=False,lvef_percent=65),'review','The lifetime risk assessment includes other anthracyclines and cannot be inferred from doxorubicin-only arithmetic.','L43–L45; L231–L239',component_attention=['doxorubicin'],match='anthracycline|exposure|lifetime')

mapbase=dict(assessment_phase='on_treatment',age_years=20,high_grade_osteosarcoma_confirmed=True,craniofacial_site=False,all_sites_completely_resectable=True,crcl_ml_min=90,indexed_gfr_ml_min_1_73m2=90,mtx_renal_plan_reconciled=True,mtx_support_and_rescue_plan_confirmed=True,hydration_urine_output_adequate=True,urine_ph=7.2)
for phase in ['hdmtx','dox_cis','surgery']:
 add('00463',f'Ongoing delayedMTXclearance remains visible after phase selector becomes{phase}',dict(**mapbase,phase=phase,hours_since_mtx_start_now=48,mtx_sample_hours_after_start=48,sample_clock_anchor='start',mtx_level_umol_l=3,mtx_clearance_delayed=True,folinic_rescue_started=True,rescue_ongoing=True),'hold','A known delayed-clearance event and toxic48-hour concentration require urgent specialist management even if a planned next component/surgery is selected. Ongoing rescue must not disappear with a selector change.','L126–L132; L153–L157; L243–L245; L453–L459',component_hold=['methotrexate'],match='clearance|rescue|methotrexate')
 add('00463',f'Known24-hour AKI and overdue rescue despite lowMTXsample, selected{phase}',dict(**mapbase,phase=phase,hours_since_mtx_start_now=36,mtx_sample_hours_after_start=24,sample_clock_anchor='start',mtx_level_umol_l=.01,creatinine_rise_percent=120,creatinine_sample_hours_after_start=24,folinic_rescue_started=False,rescue_ongoing=False),'hold','A>100% creatinine rise within24hours and absent due rescue are independently actionable; a low/older concentration or phase selection cannot remove those findings.','L126–L132; L222–L223',component_hold=['methotrexate'],match='creatinine|rescue|renal')
for request in [False,True]:
 inp={**mapbase,'phase':'rescue','urine_ph':6.8,'hours_since_mtx_start_now':72,'mtx_sample_hours_after_start':72,'sample_clock_anchor':'start','mtx_level_umol_l':.08,'folinic_rescue_started':True,'rescue_ongoing':True,'rescue_discontinuation_requested':request}
 add('00463',f'Acidic urine during ongoingrescue despite lowMTX and stoprequest{request}',inp,'hold','UrinepH≥7 is required during folinic rescue as well as infusion; low concentration alone does not resolve an active support problem or disputed rescue endpoint.','L143–L149; L253–L254',component_hold=['methotrexate'],match='pH|alkalin')
for anchor in ['start','unknown']:
 add('00463',f'Late ongoingrescue with previously escalated support and clock{anchor}',dict(**mapbase,phase='rescue',hours_since_mtx_start_now=100,mtx_sample_hours_after_start=96,sample_clock_anchor=anchor,mtx_level_umol_l=.12,folinic_rescue_started=True,rescue_ongoing=True,rescue_previously_escalated=True,rescue_deescalation_requested=True,rescue_discontinuation_requested=True),'review','At96hours a previous rescue escalation must be maintained; the conflicting clearance endpoints and an uncertain clock cannot produce numeric rescue or automatic cessation.','L250–L254; L138–L157',match='rescue|folinic')
for stage in ['baseline','on_treatment','restart']:
 inp={**mapbase,'assessment_phase':stage,'phase':'dox_cis','reference_week':12,'anc':1,'platelets':80,'counts_delay_days':9,'repeated_count_delay':True,'gcsf_given_during_delay':True,'prior_cis_count_reduction':True,'proposed_cis_count_reescalation':False}
 add('00463',f'Persistent delay history despite recovered currentcytotoxic counts, {stage}',inp,'review','A repeated>7day delay despite GCSF informs cisplatin reduction; count recovery does not automatically reset a prior reduced prescription.','L314–L325',component_attention=['cisplatin'],match='G.CSF|delay|reduction')
for stage in ['on_treatment','restart']:
 inp={**mapbase,'assessment_phase':stage,'phase':'dox_cis','reference_week':12,'crcl_ml_min':100,'indexed_gfr_ml_min_1_73m2':65,'serum_creatinine_ratio_to_baseline':1,'restart_requested':True,'restart_recovery_and_plan_confirmed':True}
 add('00463',f'HighunindexedCrCl cannot cancel lowindexedGFR duringcisplatin, {stage}',inp,'hold','Cisplatin uses indexedGFR<70 or creatinine>1.5baseline; an unindexed100mL/min result is not a substitute for the independent65mL/min/1.73m² measure.','L369–L376',component_hold=['cisplatin'])
for stage in ['on_treatment','restart']:
 inp={**mapbase,'assessment_phase':stage,'phase':'hdmtx','reference_week':15,'craniofacial_site':True}
 add('00463',f'Explicit craniofacial site outside source indication at{stage}',inp,'review','The source excludes craniofacial sites from its indication regardless of current treatment stage and otherwise favourable preparation.','L23–L25',match='craniofacial|indicat')
for stage in ['baseline','on_treatment']:
 inp={**mapbase,'assessment_phase':stage,'phase':'rescue','age_years':41,'hours_since_mtx_start_now':48,'folinic_rescue_started':True,'rescue_ongoing':True}
 add('00463',f'Age41during rescue does not imply numeric treatment or stoppingrescue, {stage}',inp,'review','The age eligibility limitation requires treatment-context review; it must not turn into an automatic rescue prescription or an instruction to stop necessary supportive treatment.','L255–L265; L222–L223',match='age|40',forbid_text='stop (?:folinic|rescue)|withhold folinic')
for phase in ['hdmtx','dox_cis']:
 add('00463',f'Confirmedpersistent postMTXhyperbilirubinaemia beyond3weeks in{phase}',dict(**mapbase,phase=phase,bilirubin_uln_multiple=1.5,persistent_hyperbilirubinaemia_days=22,mtx_liver_origin='likely_mtx',mtx_hyperbilirubinaemia_confirmed=True),'hold','Source persistence longer than3weeks invokes MTXdiscontinuation; selecting another phase must not erase the clinically confirmed MTXevent.','L405–L418',component_hold=['methotrexate'],match='bilirubin|three|3 weeks')
for phase in ['hdmtx','rescue','surgery']:
 add('00463',f'Third additionalpreoperativeMTXdose despite confirmation in{phase}',dict(**mapbase,phase=phase,reference_week=11,additional_preop_mtx=True,additional_preop_mtx_count=3,additional_preop_mtx_plan_confirmed=True),'review','The cited delayed-surgery option allows up to two additional doses; a confirmation tick cannot establish a source-supported third dose.','L33–L36',match='two|2|additional|surg')

iebase=dict(indication_code='00596a',indication_criteria_confirmed=True,anc_x10e9_l=2,platelets_x10e9_l=180,crcl_ml_min=90,haemodialysis=False,ifosfamide_product='mitoxana_pa2299_028_001',ifosfamide_laboratory_units_verified=True,serum_creatinine_umol_l=80,bilirubin_umol_l=10,alt_uln_multiple=1,ast_uln_multiple=1,alp_uln_multiple=1,ast_u_l=20,ast_units_verified=True,ifosfamide_hepatic_band='normal',ifosfamide_renal_band='ge50',etoposide_renal_band='gt50',mesna_plan_confirmed=True,hydration_plan_confirmed=True,gcsf_plan_confirmed=True,neuroassessment_completed=True,urine_assessment_completed=True,encephalopathy_grade=0,current_ifosfamide_cns_toxicity=False,prior_neurotoxicity_grade=0,current_drug_dose_known=True,current_ifosfamide_daily_mg_m2=1800,current_etoposide_daily_mg_m2=100)
for phase in ['baseline','treatment','recovery']:
 inp={**iebase,'assessment_phase':phase,'indication_code':'other','indication_criteria_confirmed':False}
 add('00596',f'Explicit unsupportedindication despite normal safety inputs at{phase}',inp,'review','Normal counts and verified product requirements do not establish one of the two labelled disease indications.','L22–L24; L76–L79',match='indicat|Ewing|osteosarcoma')
 inp={**iebase,'assessment_phase':phase,'fluid_balance_ml':2000,'weight_gain_kg':0,'fluid_balance_positive_over_1l_or_weight_gain_1kg':False,'urine_output_below_target':False}
 add('00596',f'Positivefluid balance contradicts falseaggregate flag at{phase}',inp,'review','The source calls for review when fluid balance exceeds1L OR weight rises>1kg; absence of weight gain or a negative aggregate tick cannot cancel the measured excess.','L58–L62',match='fluid|balance|weight')
for phase in ['treatment','recovery']:
 add('00596',f'Previousgrade4mucositis with currentgrade0at{phase}',dict(**iebase,assessment_phase=phase,prior_mucositis_grade=4,mucositis_grade=0,restart_requested=True),'review','The source25% reduction concerns bothdrugs after a severe mucositis/stomatitis event; symptom recovery cannot silently discard the prior dose-history review.','L180–L183',component_attention=['ifosfamide','etoposide'],match='mucositis|stomatitis')
for day in [6,7]:
 add('00596',f'Unsourced additionalcytotoxic day{day}with full currentdoses',dict(**iebase,assessment_phase='treatment',cycle_day=day,completed_cycles=2,count_delay_days=0),'review','The reference cytotoxic schedule supplies days1–5; a later day needs an explicit treatment-calendar decision rather than an automatic extra dose.','L28–L29; L37–L55',match='day|schedule|calendar')
for phase in ['treatment','recovery']:
 add('00596',f'Completed7cycles with recoveredcounts and validproduct at{phase}',dict(**iebase,assessment_phase=phase,completed_cycles=7,cycle_day=1,mucositis_grade=0),'review','The source maximum is seven cycles; favourable current testing does not authorise an eighth cycle.','L28–L29',match='7|seven|cycle|course')
for units in [False,True]:
 inp={**iebase,'assessment_phase':'treatment','ast_u_l':250,'ast_units_verified':units,'ast_uln_multiple':1,'etoposide_hepatic_band':'normal'}
 add('00596',f'AbsoluteAST250with reassuringselectedband and unitsverified{units}',inp,'review','The etoposide source uses absolute AST thresholds with unspecified printedunits; contradictory band/localULN entries require specific reconciliation, not an invented hepaticpercentage or clearance.','L129–L141',component_attention=['etoposide'],match='AST|hepatic|liver|unit')
for grade in [3,4]:
 add('00596',f'Currentgrade{grade}mucositis with no neurologicalevent',dict(**iebase,assessment_phase='treatment',mucositis_grade=grade,prior_mucositis_grade=0,aprepitant_planned=True),'review','Severe mucositis affects bothcytotoxics; aprepitant/CNSreview is an additional issue and must not erase the separate two-drug adjustment pathway.','L180–L183; L199–L203',component_attention=['ifosfamide','etoposide'],match='mucositis|stomatitis')

counts={k:sum(c['code']==k for c in cases) for k in urls};assert counts=={'00420':20,'00463':24,'00596':16},counts
assert len({(c['code'],json.dumps(c['inputs'],sort_keys=True)) for c in cases})==60
Path(__file__).with_name('core-cases.json').write_text(json.dumps({'design':'Fresh source-first cross-risk/context/chronology checks against acceptedv63candidates, not old applicationJSON.','clinical_approval':False,'cases':cases},indent=2)+'\n')
print(counts)
